"use client";

import { type HTMLAttributes, type Ref, useRef } from "react";
import { useLightField, useReveal } from "../interaction/hooks";
import type { LightFieldOptions } from "../interaction/light";
import type { RevealOptions } from "../interaction/reveal";

export type LightFieldProps = HTMLAttributes<HTMLDivElement> & LightFieldOptions & { ref?: Ref<HTMLDivElement> };

/**
 * Feeds pointer position to every lit or holo surface inside it (and to an Atmosphere). One listener for the whole
 * region; children stay server components.
 */
export function LightField({ selector, tilt, track, ease, ref, ...rest }: LightFieldProps) {
  const own = useRef<HTMLDivElement>(null);
  useLightField(own, { selector, tilt, track, ease });
  return <div {...rest} ref={mergeInto(own, ref)} />;
}

export type RevealProps = HTMLAttributes<HTMLDivElement> & RevealOptions & { ref?: Ref<HTMLDivElement> };

/**
 * Reveals `[data-hm-reveal]` descendants (and itself, if marked) as they scroll into view. Stagger siblings with
 * `style={{ "--hm-i": n }}`.
 */
export function Reveal({ selector, rootMargin, once, ref, ...rest }: RevealProps) {
  const own = useRef<HTMLDivElement>(null);
  useReveal(own, { selector, rootMargin, once });
  return <div {...rest} ref={mergeInto(own, ref)} />;
}

function mergeInto<T>(own: { current: T | null }, ref?: Ref<T>) {
  return (node: T | null) => {
    own.current = node;
    if (typeof ref === "function") return ref(node);
    if (ref) (ref as { current: T | null }).current = node;
  };
}
